begin;
insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data) values(gen_random_uuid(),'stock-owner-fixture@example.invalid',now(),'{}','{}'),(gen_random_uuid(),'stock-buyer-fixture@example.invalid',now(),'{}','{}');
insert into corporate_private.staff_grants(email,staff_role) values('stock-owner-fixture@example.invalid','owner');
insert into public.corporate_products(sku,title,price_cents,stock) values('__tg_stock_fixture','Stock fixture',1000,10),('__tg_stock_unknown','Unknown fixture',1000,null);
select set_config('request.jwt.claim.sub',(select id::text from auth.users where email='stock-owner-fixture@example.invalid'),true);
set local role authenticated;
do $$declare stamp timestamptz; retry_key uuid:=gen_random_uuid(); first_result jsonb; second_result jsonb; history jsonb;begin
 select updated_at into stamp from public.corporate_products where sku='__tg_stock_fixture';
 first_result:=public.corporate_adjust_stock('__tg_stock_fixture','received',5,'Delivery note 123',stamp,retry_key);
 if first_result->>'new_stock'<>'15' then raise exception 'Received calculation failed';end if;
 second_result:=public.corporate_adjust_stock('__tg_stock_fixture','received',5,'Delivery note 123',stamp,retry_key);
 if first_result is distinct from second_result then raise exception 'Retry is not idempotent';end if;
 begin perform public.corporate_adjust_stock('__tg_stock_fixture','received',6,'Delivery note 123',stamp,retry_key);raise exception 'Changed retry accepted';exception when others then if sqlerrm<>'adjustment_changed' then raise;end if;end;
 begin perform public.corporate_adjust_stock('__tg_stock_fixture','lost',1,'Old stock count',stamp,gen_random_uuid());raise exception 'Stale update accepted';exception when others then if sqlerrm<>'record_changed' then raise;end if;end;
 select updated_at into stamp from public.corporate_products where sku='__tg_stock_fixture';
 begin perform public.corporate_adjust_stock('__tg_stock_fixture','damaged',16,'Damage report',stamp,gen_random_uuid());raise exception 'Negative stock accepted';exception when others then if sqlerrm<>'stock_bounds' then raise;end if;end;
 perform public.corporate_adjust_stock('__tg_stock_fixture','damaged',2,'Damage report',stamp,gen_random_uuid());
 select updated_at into stamp from public.corporate_products where sku='__tg_stock_fixture';
 perform public.corporate_adjust_stock('__tg_stock_fixture','returned',1,'Inspected sellable return',stamp,gen_random_uuid());
 select updated_at into stamp from public.corporate_products where sku='__tg_stock_fixture';
 perform public.corporate_adjust_stock('__tg_stock_fixture','lost',1,'Missing item',stamp,gen_random_uuid());
 select updated_at into stamp from public.corporate_products where sku='__tg_stock_fixture';
 perform public.corporate_adjust_stock('__tg_stock_fixture','count',0,'Physical count zero',stamp,gen_random_uuid());
 select updated_at into stamp from public.corporate_products where sku='__tg_stock_unknown';
 begin perform public.corporate_adjust_stock('__tg_stock_unknown','received',1,'No known baseline',stamp,gen_random_uuid());raise exception 'Unknown baseline accepted';exception when others then if sqlerrm<>'stock_unknown' then raise;end if;end;
 perform public.corporate_adjust_stock('__tg_stock_unknown','count',3,'Physical baseline',stamp,gen_random_uuid());
 select updated_at into stamp from public.corporate_products where sku='__tg_stock_unknown';
 perform public.corporate_edit_product('__tg_stock_unknown','Unknown fixture','',1000,4,stamp);
 history:=public.corporate_stock_history('__tg_stock_unknown',0);
 if jsonb_array_length(history)<>3 or history->0->>'reason'<>'catalogue_update' then raise exception 'Legacy stock edit missing from history';end if;
 if history->1->>'actor_label'<>'stock-owner-fixture@example.invalid' then raise exception 'Actor missing';end if;
 if public.corporate_stock_history('__tg_stock_unknown',50)<>'[]'::jsonb then raise exception 'History pagination failed';end if;
 begin perform public.corporate_adjust_stock('__tg_stock_fixture','received',0,'Bad quantity',stamp,gen_random_uuid());raise exception 'Zero receipt accepted';exception when others then if sqlerrm<>'invalid_adjustment' then raise;end if;end;
 begin update public.corporate_products set stock=100 where sku='__tg_stock_fixture';raise exception 'Direct stock edit accepted';exception when insufficient_privilege then null;end;
 begin delete from corporate_private.stock_movements;raise exception 'History deletion accepted';exception when insufficient_privilege then null;end;
end;$$;
reset role;
select set_config('request.jwt.claim.sub',(select id::text from auth.users where email='stock-buyer-fixture@example.invalid'),true);
set local role authenticated;
do $$begin
 begin perform public.corporate_stock_history('__tg_stock_fixture');raise exception 'Customer history access accepted';exception when others then if sqlerrm<>'Store administrator required' then raise;end if;end;
 begin perform public.corporate_adjust_stock('__tg_stock_fixture','received',1,'Buyer attempt',now(),gen_random_uuid());raise exception 'Customer stock write accepted';exception when others then if sqlerrm<>'Store administrator required' then raise;end if;end;
end;$$;
reset role;
select set_config('request.jwt.claim.sub','',true);
set local role anon;
do $$begin begin perform public.corporate_stock_history('__tg_stock_fixture');raise exception 'Anonymous access accepted';exception when insufficient_privilege then null;end;end;$$;
reset role;
select 'inventory workflow, retries, bounds, auditing and role checks passed' as result;
rollback;
